(function(){"use strict";const started=performance.now();let count=0,total=0,max=0;try{new PerformanceObserver(list=>{for(const e of list.getEntries()){count++;total+=e.duration;max=Math.max(max,e.duration)}}).observe({type:"longtask",buffered:true})}catch(_){}window.opmPerformanceSummary=()=>{const n=performance.getEntriesByType("navigation")[0],r=performance.getEntriesByType("resource");return Object.freeze({version:"v157",domReadyMs:n?Math.round(n.domContentLoadedEventEnd):null,loadMs:n?Math.round(n.loadEventEnd):null,observedMs:Math.round(performance.now()-started),longTaskCount:count,longTaskTotalMs:Math.round(total),longTaskMaxMs:Math.round(max),resourceCount:r.length,staticAssetCount:r.filter(x=>/\/assets\//.test(x.name)).length,jsHeapMB:performance.memory?Math.round(performance.memory.usedJSHeapSize/1048576):null})};})();